WITH base AS (SELECT toDate(occurred_at) AS `day`, COUNT(projection_for_dataset_queries_events.event_id) AS `events`, SUM(projection_for_dataset_queries_events.latency_ms) AS `totalLatencyMs` FROM projection_for_dataset_queries_events WHERE toDate(occurred_at) BETWEEN ? AND ? GROUP BY `day`) SELECT `day`, `events`, `totalLatencyMs`, (toFloat64(`totalLatencyMs`) / NULLIF(`events`, 0)) AS `avgLatencyMs` FROM base ORDER BY `day` ASC
